CATALOG={r['id']:r for r in json.loads(Path('.cache/catalog.json').read_text())}
def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=CATALOG[ASSIGN['roots'][i]['id']];allwords=set(r['family'])|set(r['words'])|set(r['unmatched'])|set(ASSIGN['roots'][i]['family'])
 return {w:DEFERRED[w] for w in sorted(allwords) if w in DEFERRED}
OCUL_ROOT=dict(id='C0858',meaning='眼；芽眼；像眼的圆形开口',core='眼睛是看出去的开口；植物的芽、建筑的圆洞，也借用眼的形象。',image='拉丁 oculus → ocularis → ocular；oculus 直接借为 oculus。单眼、双眼成分接出 monocular、binocular；in- + oculus 芽 → inoculare → inoculate／inoculatio → inoculation。',intro='先把 ocular、monocular 与 binocular 看成一只眼或两只眼。oculus 常用于建筑圆形开口。inoculate 这一支最容易误解：拉丁 oculus 在这里是芽眼，先说嫁接，后来才用于接种，不是向眼睛注入东西。',forms='ocular 与 oculus 各自借入，不能依英语今天的拼写假定先后。inoculate 只有一个 n，常见拼写错误是多写成双 n。inoculation 有独立拉丁名词路线，其医学义还影响了英语动词。',branches=[['眼及单眼、双眼','ocular, monocular, binocular, binoculars, intraocular'],['建筑圆形开口','oculus'],['芽眼嫁接到接种','inoculate, inoculation']],contrasts='ocular 直接指眼器官，visual 更常说视觉表现，optical 常涉及光与光学。injection 是注射，inoculation 是接种，不能把一切注射都叫接种。',practice='说明 oculus 的圆洞与 inoculate 的芽眼怎样借用眼的形象；比较 monocular 与 binoculars；分别用 inoculate against 和 inoculation 造句。',words=rootwords(198,['binocular','binoculars']),exclude=rootexclude(198))
KUDO_ROOT=dict(id='C0637',meaning='荣誉；名望；赞扬',core='把赞赏和功劳给到做得好的人：Kudos to you! 就是干得漂亮。',image='希腊 kydos 荣誉、名望 → 英语 kudos → 日常直接称赞某人或某个团队。',intro='这根最实用的词就是 kudos。不要先看到末尾 s 就断定它是英语复数；希腊原词就是带 s 的单数形式，英语通常作为不可数赞誉使用。',forms='英式常读 /ˈkjuːdɒs/，美式存在 /ˈkuːdɑːs/、/ˈkuːdoʊz/ 等读法。现代 kudo 是后来重新分析词尾形成的形式，不是古希腊词的起点。',branches=[['赞赏与获得声望','kudos']],contrasts='kudos 常肯定做得好的行动，congratulations 更常祝贺喜事。不要为了数一次表扬而机械删去末尾 s；可以直接说 give somebody kudos。',practice='用 Kudos to somebody for doing something 表扬一项具体工作；再用 earn kudos 描述一个团队如何赢得认可。',words=rootwords(199),exclude=rootexclude(199))
CENTEN_ROOT=dict(id='C0197',meaning='每一百；百年；百周年',core='把一百年作为一个单位，能数出百周年、二百周年、三百周年，也能说活到百岁的人。',image='拉丁 centum 一百 → centeni 每一百 → centenarius → centenary；英语加 bi-/ter- → bicentenary/tercentenary；centenary + -ian → centenarian。centennial/bicentennial 为相关百年命名支线。',intro='centenary 主要说一个事件的百周年，centenarian 主要说百岁老人。bi- 把百年数到二，ter- 把百年数到三。centennial 与 bicentennial 也是常见周年表达，但不能把不同词形都画成现代 centenary 直接派生。',forms='centenary 英美常见重音相同而重读元音不同：英 /tiː/，美 /te/。centenarian 的重音移到 -nar- 一段。tercentenary 的 ter- 是三，不是磨擦的 ter-。',branches=[['百周年及其纪念','centenary, centennial'],['二百与三百周年','bicentenary, bicentennial, tercentenary'],['百岁老人','centenarian']],contrasts='century 是百年时期，centenary 是特定起点满百年的节点；centenarian 说年龄。bicentenary 与 biennial、biannual 都不同，后两词不是二百周年。',practice='为一所建立一百年、二百年、三百年的学校分别写一句纪念用语；再用 centenarian 描述一位一百零三岁的老人。',words=rootwords(200,['centennial','bicentennial']),exclude=rootexclude(200))
POR_ROOT=dict(id='C1101',meaning='通道；孔；旅行往来的路线',core='小处是能通过水或空气的孔，大处是商人来往的道路。',image='希腊 poros → 拉丁 porus → pore；porosus/porositas 经法语成 porous/porosity → nonporous。希腊 en- + poros → emporos 商人 → emporion → emporium。',intro='pore、porous、porosity 讲孔及孔隙，nonporous 讲不易渗入的表面。emporium 藏着旅行经商的历史，后来成为商品丰富的大店。仔细研读的 pore over 是另一个来源不明的动词，在词条中单独解释。',forms='porous 的重音在开头，porosity 在第二音节。英语 pore 的末尾 e 不单独发音。emporium 的 em- 来自希腊 en- 的同化，不从 empire 帝国派生。',branches=[['小孔与多孔性质','pore, porous, porosity, nonporous'],['商旅与商店','emporium']],contrasts='porosity 说孔隙所占空间，permeability 说流通难易；两者有关但不等同。pore over 是仔细研读，pour over 是倒在上面；同音而不同词。',practice='用一块海绵说明 pore、porous、porosity 的关系；用商旅来往解释 emporium；分别给 pore over 与 pour over 一个宾语。',words=rootwords(201),exclude=rootexclude(201))
POT_ROOT=dict(id='C1109',meaning='喝；饮料；药饮',core='喝下去的一口液体，可以是普通饮料、药水，也可能是毒饮；不同路线把词义带向不同方向。',image='拉丁 potare 喝 → potio/potionem；经古法语 pocion 成 potion，经 poison/puison 成 poison。potabilis 经法语成 potable；英语 poison 派生 poisonous、poisoned、poisoning。',intro='potion 与 poison 是同一个拉丁词经不同路线形成的同源双词：今天一个常见于魔药故事，一个说毒物。potable 关心能否饮用。poisoned 与 poisonous 还要分清受毒害后的状态和具有毒性这一性质。',forms='potable 的开头常读 /pəʊ/ 或 /poʊ/，不是 portable 可携带的。这个 pot- 喝与英语 pot 锅的来源不同。poisoning 的 -ing 可以是动词形式，也可组成中毒这一名词。',branches=[['药饮与饮用条件','potion, potable'],['毒物与毒害','poison, poisonous'],['中毒过程与受影响状态','poisoning, poisoned']],contrasts='potion 不必有毒，poison 不限液体。food poisoning 不表示必定有人蓄意投毒。poisonous 说有毒性，poisoned 说已经受影响；比喻时也常涉及恶意和不信任。',practice='比较 a poisonous plant 与 poisoned water；解释 potion 与 poison 为何同源却不是互相加后缀；用 poison 描述信任被破坏。',words=rootwords(202),exclude=rootexclude(202))
BYSS_ROOT=dict(id='C0150',meaning='底；无底的深处',core='把底拿掉，就像掉进看不到尽头的深处；这个画面既能说深海，也能说糟糕到谷底。',image='希腊 a- 无 + byssos 底 → abyssos → 拉丁 abyssus → abyss → abyssal；另经古法语 abisme 成 abysm → abysmal → abysmally。',intro='abyss 是深渊，abyssal 今天多用于深海。abysmal 经旧词 abysm 这一支而来，今天通常说糟糕透顶。差别不只在有没有 m，也在各自最常出现的场景。',forms='abysmal 不能硬拆成 abyss 加拉丁 mal 坏；它是 abysm 加 -al。abyssal 中间读 /s/，abysmal 中间读 /z/。abysm 的中间拉丁形式是重建，不写成有完整实证的确定记录。',branches=[['深渊与深海','abyss, abyssal'],['极差的评价','abysmal, abysmally']],contrasts='abyssal plain 是深海平原，不是糟糕的平原；abysmal service 是差劲服务，不是在海底服务。历史义项会重叠，现代常用搭配仍应分开。',practice='各写一句 an abyss of despair、an abyssal plain、abysmal service；用读音记住 abyssal 的 /s/ 和 abysmal 的 /z/。',words=rootwords(203),exclude=rootexclude(203))
AUDAC_ROOT=dict(id='C0095',meaning='敢；大胆；胆量',core='敢跨出旁人会犹豫的一步：可能令人佩服，也可能让人觉得太放肆。',image='拉丁 audere 敢 → audax，词干 audac- → audacitas → audacity；audacia 经法语 audacieux → audacious → audaciously。',intro='这一族不能只背正面的勇敢。the audacity of a plan 可以是赞赏，have the audacity to blame someone 常在批评居然有脸责怪别人。先抓大胆，再从语境判断褒贬。',forms='audacity 重读 /dæs/，audacious 重读 /deɪ/。形容词经过法语借入，不是英语 audacity 直接派生的唯一历史。这里 aud- 敢与 audio 声音不是同一个词根。',branches=[['胆量与放肆','audacity'],['大胆的行动和方式','audacious, audaciously']],contrasts='courage 常赞面对困难仍勇敢；audacity 更强调冒险、越界。reckless 一般批评不顾后果，audacious 可以表达佩服。',practice='用 audacity 各写一个称赞和一个责备的句子；把一个 ambitious plan 改写成 audacious plan，说明语感增加了什么。',words=rootwords(204),exclude=rootexclude(204))
SAPPHIR_ROOT=dict(id='C1258',meaning='古代蓝色珍贵石料；现代蓝宝石',core='名字让人想到浓郁的蓝色，但现代宝石类别并不只容纳蓝色。',image='希腊 sappheiros → 拉丁 sapphirus → 古法语 saphir／英语 sapphire；更早常联系闪米特语，确切路线不完全清楚。',intro='先掌握 sapphire 这个常见珠宝词即可。古代名称可能指青金石，现代 sapphire 则用于刚玉宝石类别中的非红宝石部分；不能仅凭名字相同，就把古今石料当作同一种矿物。',forms='ph 读 /f/，末尾 -ire 在英美读法中有是否发 r 的差别。原词根表把更早来源简写为希伯来语，实际传借细节不宜说得过于确定。',branches=[['宝石与蓝色','sapphire']],contrasts='蓝色是 sapphire 最熟悉的颜色，但也有粉、黄等颜色。ruby 是红宝石；lapis lazuli 是青金石，现代不能与 sapphire 互换。',practice='用 sapphire ring 和 sapphire blue 各造一句；解释为什么 pink sapphire 这个表达并不自相矛盾。',words=rootwords(205),exclude=rootexclude(205))
PONDER_ROOT=dict(id='C1098',meaning='重量；称量；比较分量',core='把事情放到秤上：心里称一称是 ponder，重得难挪是 ponderous，一边更有分量是 preponderance。',image='拉丁 pondus，词干 ponder- → ponderare 称重 → ponder；ponderosus → ponderous → ponderously。prae- + ponderare → praeponderare、praeponderans → preponderant／preponderance。',intro='这一组很适合用同一架秤分三条支线记忆。ponder 说思考，ponderous 说笨重沉闷，preponderance 说比较后占优势。不能因同源就把 ponderous 理解成善于深思。',forms='pondus 的屈折词干显出 ponder-。preponderant 来自拉丁分词，英语记录早于动词 preponderate，历史路线不从后来的英语动词倒推。preponderance 的现代 -ance 名词关系可另作构词理解。',branches=[['在心里掂量','ponder'],['笨重、沉闷','ponderous, ponderously'],['比较后的优势','preponderance, preponderant']],contrasts='thoughtful 可以是深思或体贴，ponderous 往往是负面评价。abundance 是很多，preponderance 重点是相对另一方更多或更有分量。',practice='先用 ponder 认真考虑问题，再用 ponderous 描写拖沓讲话；最后用 preponderance 比较两类证据或群体的分量。',words=rootwords(206),exclude=rootexclude(206))
PRODIG_ROOT=dict(id='C1134',meaning='异兆；非同寻常的现象；令人惊异',core='原先是异常到被当成征兆的事情，后来变成才能、大小或数量惊人。',image='拉丁 prodigium → 古法语 prodige／英语 prodigy → 非凡人才、神童；prodigium → prodigiosus → 法语 prodigieux／英语 prodigious → prodigiously。',intro='prodigy 常说年少便才能出众的人；prodigious 说规模、数量、能力惊人，并不只修饰神童。两词有共同拉丁来源，但形容词经过自己的借入路线。',forms='prodigy 开头重读，prodigious 和 prodigiously 重读第二音节。拉丁 prodigium 内部的 -igium 来源仍有争议，不能强行拆成一套确定的现代字母含义。',branches=[['神童与非凡人才','prodigy'],['令人惊异的量或程度','prodigious, prodigiously']],contrasts='prodigal 挥霍的接拉丁 prodigus，不能当作 prodigy 直接派生。prodigious 可以说才能惊人，也可说浪费惊人；程度极大不自动等于赞扬。',practice='用 child prodigy 描写一个人物，再用 a prodigious amount of work 描写工作量；解释两个词虽然同源，语法和现代使用范围为何不同。',words=rootwords(207),exclude=rootexclude(207))
